 'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
 'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
 'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def translate(s):
    return ''.join(table.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

START = ('ATG','GTG','TTG')
STOPS = ('TAA','TAG','TGA')

def orfs(s, strand, min_aa=50):
    out=[]
    for frame in range(3):
        i=frame
        while i <= len(s)-3:
            if s[i:i+3] in START:
                j=i
                while j <= len(s)-3 and s[j:j+3] not in STOPS:
                    j+=3
                aa=(j-i)//3
                if aa>=min_aa:
                    if strand=='+':
                        out.append((strand, frame+1, i+1, j+2, aa, s[i:j]))
                    else:
                        # rc index i -> plus coordinate L-i ; end rc j -> plus L-j-1
                        out.append((strand, frame+1, L-j-1+1, L-i, aa, s[i:j]))
                i=j+3
            else:
                i+=3
    return out

